const leverStyle=document.createElement('style');leverStyle.textContent=`.leverbank{margin:0 0 22px;background:linear-gradient(#303b37,#18231f);border:1px solid #5a6a5e;border-radius:10px;padding:20px;box-shadow:inset 0 1px #7c8a7133}.levergrid{display:grid;grid-template-columns:repeat(8,1fr);gap:10px}.leverunit{text-align:center;min-width:80px}.lever{height:142px;width:100%;position:relative;overflow:hidden;background:linear-gradient(90deg,#19211d,#3b463e 50%,#19211d);border:1px solid #71806c;border-radius:8px;padding:0}.lever .slot{position:absolute;width:12px;height:95px;left:calc(50% - 6px);top:22px;background:#0a120d;border-radius:10px;box-shadow:inset 0 0 5px black}.lever .arm{position:absolute;left:calc(50% - 5px);top:58px;width:10px;height:62px;border-radius:4px;background:linear-gradient(90deg,#788479,#d9e1d0,#677365);transform-origin:50% 55px;transform:rotate(30deg);transition:transform .23s}.lever .grip{position:absolute;left:-9px;top:-15px;width:28px;height:38px;border-radius:9px;background:linear-gradient(90deg,#732e28,#e37a5f,#7f342a);box-shadow:0 3px 4px #0008}.lever.point .grip{background:linear-gradient(90deg,#243c61,#8db6df,#344e78)}.lever.reverse .arm{transform:rotate(-30deg)}.lever.locked{border-color:#c8a666}.lever.locked:after{content:'鎖錠';position:absolute;bottom:8px;right:7px;font-size:10px;color:#f4d08b}.levernum{font:700 18px ui-monospace,monospace;color:#f2e9bd;margin-bottom:8px}.leverstate{font-size:12px;color:#bfd4bf;min-height:20px;margin:7px 0}.levercaption{font-size:12px;color:#a9bba9}.leverhint{padding:12px 15px;background:#132219;border-left:3px solid #aec98a;margin:16px 0 0;color:#d3e4bd;line-height:1.7;font-size:14px}.lamp{display:inline-block;width:7px;height:7px;border-radius:100%;background:#a9c584;margin-right:7px}.levernote{color:#9eafa5;font-size:12px;line-height:1.7}@media(max-width:900px){.levergrid{grid-template-columns:repeat(4,1fr)}}` ;document.head.append(leverStyle);
const bank=document.createElement('section');bank.className='leverbank';bank.innerHTML=`<div class="row" style="justify-content:space-between;margin-top:0"><h2 style="margin:0">テコ扱所</h2><small>青：転てつテコ　赤：信号テコ</small></div><p class="levernote">定位＝通常位置 ／ 反位＝倒した位置。テコをクリックすると切り替わります。</p><div class="levergrid" id="levergrid"></div><div class="leverhint" id="leverhint"></div>`;document.querySelector('.columns').before(bank);
const grid=$('levergrid');for(let i=0;i<8;i++){const point=i<2,n=point?i+1:(i-2)%3+1,d=i<5?'in':'out',id=point?'W'+n:(d==='in'?'S':'D')+n;let unit=document.createElement('div');unit.className='leverunit';unit.innerHTML=`<div class="levernum">${id}</div><button class="lever ${point?'point':''}" id="lever${i}" aria-label="${id} ${point?'転てつ':d==='in'?'入場':'出発'}テコ"><span class="slot"></span><span class="arm"><span class="grip"></span></span></button><div class="leverstate" id="leverstate${i}">定位</div><div class="levercaption">${point?'転てつ器 '+n:(d==='in'?'入場 → ':'出発 ← ')+n+'番線'}</div>`;grid.append(unit);$('lever'+i).onclick=()=>{if(play.ended)return;if(point)return toggle(i);if(s.r){if(s.r.n===n&&s.r.d===d)return cancel();return tell('信号テコ操作不可：共通のど部の競合進路が鎖錠中です。')}const needed=req(n);if(s.w.some((v,j)=>v!==needed[j]))return tell(`信号テコ ${id} は動きません。転てつ器不一致：W1を${needed[0]?'反位':'定位'}、W2を${needed[1]?'反位':'定位'}に合わせてください。`);$('dir').value=d;$('dest').value=String(n);setRoute()}}
// All route requests use the same point correspondence check; no automatic point movement.
const previousSet=setRoute;setRoute=()=>{let n=+$('dest').value,w=req(n);if(!s.r&&s.w.some((v,i)=>v!==w[i]))return tell('転てつ器不一致。黒い転てつテコで進路を合わせてください。');previousSet()};$('set').onclick=setRoute;
const beforeLeverRender=render;render=()=>{beforeLeverRender();let r=s.r;for(let i=0;i<8;i++){let point=i<2,n=(i-2)%3+1,d=i<5?'in':'out',active=point?!!s.w[i]:!!(r&&r.n===n&&r.d===d&&r.green),locked=point?switchLocked():!!r;let el=$('lever'+i);el.classList.toggle('reverse',active);el.classList.toggle('locked',locked);el.setAttribute('aria-pressed',String(active));$('leverstate'+i).textContent=active?'反位'+(point?'':' · 進行'):'定位'+(point?'':' · 停止');}let n=s.train?.loc?.startsWith('P')?+s.train.loc.slice(1):s.goal,w=req(n);$('leverhint').textContent=r? r.cancel!==null?`信号テコ復位。接近鎖錠の解錠まで ${Math.ceil(r.cancel)} 秒。`:r.stage>=0?'列車通過中。進路内のテコ鎖錠を監視してください。':'信号開通。列車が進入すると信号は停止へ自動復位します。':!s.train?'次の列車を呼んで、次の運転へ。':`手順：W1＝${w[0]?'反位':'定位'} ／ W2＝${w[1]?'反位':'定位'} → ${s.train.loc==='A'?'S':'D'}${n} 信号テコを反位へ。`;
if(!r&&s.train){$('next').textContent=s.train.loc==='A'?`${n}番線へ · 転てつテコ → S${n}`:`${n}番線から出発 · D${n}`;$('tip').textContent='下のテコ扱所で、黒い転てつテコを合わせてから赤い信号テコを操作します。'} };
// Keep the compact train controls, and replace duplicate route controls with lever guidance.
$('dir').closest('.row').style.display='none';$('w1').closest('.row').style.display='none';$('w1').closest('section').querySelectorAll('h3')[0].textContent='テコ操作のポイント';$('w1').closest('section').querySelector('small').textContent='進路はテコ扱所で設定します。黒テコで配線を合わせ、目的の赤テコを反位にしてください。';$('dest').value='2';
document.querySelector('details').innerHTML=`<summary>遊び方と鎖錠ルール</summary><p>① 運転ナビの指示に合わせてW1・W2の黒い転てつテコをクリック。② 指定番線の入場信号テコS1〜S3を反位にすると列車が入場。③ 到着・進路解錠後、同番線の出発信号テコD1〜D3を反位にして出発。④ 次の列車を呼びます。正しい番線への到着で得点。3分チャレンジでは定着と連続成功を狙いましょう。</p><p>転てつ器対応：1番線＝W1反位・W2定位（側面防護）。2番線＝両方定位。3番線＝W1定位・W2反位。不一致では信号テコを反位にできません。</p><p>進路を構成すると、関係する転てつ器を鎖錠します。列車進入後は進路鎖錠を保持します。てっ査鎖錠：T在線中は転てつ器の転換を禁止します。競合する進路：共通の転てつ区間を使う他の進路は構成できません。着点在線時の入場、列車のいない番線からの出発も禁止。</p><p>接近鎖錠：接近列車がある状態で進行を指示する信号を現示すると成立。赤テコを戻しても、20秒の時素が満了するまで進路と転てつ器を鎖錠します。進入後の取消は信号停止のみで通過まで鎖錠保持。列車進入時に信号は自動停止。区分解錠は列車後尾のT通過確認後、進路全体は到着または退出確認後に行います。</p><p>架空駅の簡略シミュレーターです。実物の方式ごとに異なるテコ・鎖錠のすべては再現していません。20秒はゲーム用短縮時分。タブが非表示の間は時間が止まります。</p>`;render();

